import{_ as o,o as e,c as t,a0 as c}from"./chunks/framework.DqMqoJl9.js";const _=JSON.parse('{"title":"Исходный код и модели","description":"","frontmatter":{},"headers":[],"relativePath":"source-code/index.md","filePath":"source-code/index.md"}'),a={name:"source-code/index.md"};function r(l,d,s,n,i,m){return e(),t("div",null,[...d[0]||(d[0]=[c('<h1 id="исходныи-код-и-модели" tabindex="-1">Исходный код и модели <a class="header-anchor" href="#исходныи-код-и-модели" aria-label="Permalink to &quot;Исходный код и модели&quot;">​</a></h1><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>Описание структуры исходного кода, основных модулей и сопоставления моделей данных с таблицами БД.</p><h2 id="структура-проектов" tabindex="-1">Структура проектов <a class="header-anchor" href="#структура-проектов" aria-label="Permalink to &quot;Структура проектов&quot;">​</a></h2><ul><li><strong>Common.Data</strong> — Базовые модели, провайдеры, интерфейсы доступа к данным.</li><li><strong>Umms.Core</strong> — Ядро бизнес-логики (ПО СС / ПО МС).</li><li><strong>Umms.Service</strong> — Сервисный слой, реализация сценариев.</li><li><strong>Umms.UsbExchange</strong> — Модуль обмена данными по USB (АРМ МС).</li></ul><h2 id="основные-модули-по-сс-по-мс" tabindex="-1">Основные модули ПО СС / ПО МС <a class="header-anchor" href="#основные-модули-по-сс-по-мс" aria-label="Permalink to &quot;Основные модули ПО СС / ПО МС&quot;">​</a></h2><ul><li><strong>Лица</strong> (<code>UmmsPersonModel</code>) — управление физическими лицами.</li><li><strong>Документы</strong> (<code>UmmsDocumentModel</code>) — учет документов, удостоверяющих личность.</li><li><strong>Дела</strong> (<code>UmmsCaseModel</code>) — оформление услуг и дел.</li><li><strong>Адреса</strong> (<code>UmmsAddressModel</code>) — регистрация и адресные справочники.</li></ul><h2 id="сценарии-no-1-выдача-нового-документа-откат" tabindex="-1">Сценарий № 1 (Выдача нового документа / откат) <a class="header-anchor" href="#сценарии-no-1-выдача-нового-документа-откат" aria-label="Permalink to &quot;Сценарий № 1 (Выдача нового документа / откат)&quot;">​</a></h2><ul><li><code>issueNewDocument</code>: Создание нового документа, привязка к делу и лицу.</li><li><code>RollbackScenario1</code>: Откат операции (отправляет пустой объект, особенность транзакций).</li></ul><h2 id="usb-обмен-арм-мс" tabindex="-1">USB-обмен (АРМ МС) <a class="header-anchor" href="#usb-обмен-арм-мс" aria-label="Permalink to &quot;USB-обмен (АРМ МС)&quot;">​</a></h2><ul><li>Синхронизация справочников (страны, документы).</li><li>Примечание: <code>getCountryDictionary</code> в коде не вызывается — клиент использует локальный файл <code>dict_country.csv</code>.</li></ul><h2 id="соответствие-моделеи-кода-и-таблиц-бд" tabindex="-1">Соответствие моделей кода и таблиц БД <a class="header-anchor" href="#соответствие-моделеи-кода-и-таблиц-бд" aria-label="Permalink to &quot;Соответствие моделей кода и таблиц БД&quot;">​</a></h2><h3 id="common-data-models-umms-→-таблицы-core" tabindex="-1">Common.Data.Models.Umms → Таблицы CORE_* <a class="header-anchor" href="#common-data-models-umms-→-таблицы-core" aria-label="Permalink to &quot;Common.Data.Models.Umms → Таблицы CORE_*&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Модель</th><th>Таблица</th><th>Примечание</th></tr></thead><tbody><tr><td><code>UmmsPersonModel</code></td><td><code>CORE_PERSON</code>, <code>CORE_PERSONDATA</code></td><td>Основные данные лица + персональные данные</td></tr><tr><td><code>UmmsDocumentModel</code></td><td><code>CORE_DOCUMENT</code></td><td>Документы, удостоверяющие личность</td></tr><tr><td><code>UmmsCaseModel</code></td><td><code>CORE_CASE</code>, <code>CORE_PERSON_CASE</code></td><td>Дело + связь лица с делом</td></tr><tr><td><code>UmmsAddressModel</code></td><td><code>CORE_ADDRESS</code>, <code>CORE_PERSON_ADDRESS</code></td><td>Адрес + привязка адреса к лицу</td></tr><tr><td><code>CountryModel</code></td><td><code>DICT_COUNTRY</code></td><td>Справочник стран</td></tr><tr><td><code>UmmsOrgModel</code></td><td><code>CORE_ORGANIZATION</code></td><td>Организации/УФМС</td></tr><tr><td><code>UmmsPaymentModel</code></td><td><code>CORE_PAYMENT</code></td><td>Платежи</td></tr></tbody></table><h3 id="common-data-providers-→-запросы-к-бд" tabindex="-1">Common.Data.Providers → Запросы к БД <a class="header-anchor" href="#common-data-providers-→-запросы-к-бд" aria-label="Permalink to &quot;Common.Data.Providers → Запросы к БД&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Провайдер</th><th>Используемые таблицы</th><th>Описание</th></tr></thead><tbody><tr><td><code>PersonProvider</code></td><td><code>CORE_PERSON</code>, <code>CORE_PERSONDATA</code>, <code>CORE_PERSON_ADDRESS</code></td><td>Получение/сохранение данных лица</td></tr><tr><td><code>DocumentProvider</code></td><td><code>CORE_DOCUMENT</code>, <code>DICT_DOCUMENT_TYPE</code></td><td>Работа с документами</td></tr><tr><td><code>CaseProvider</code></td><td><code>CORE_CASE</code>, <code>CORE_PERSON_CASE</code>, <code>CORE_CASE_STATUS</code></td><td>Управление делами</td></tr><tr><td><code>CountryProvider</code></td><td><code>DICT_COUNTRY</code></td><td>Справочник стран</td></tr><tr><td><code>AddressProvider</code></td><td><code>CORE_ADDRESS</code>, <code>CORE_PERSON_ADDRESS</code>, <code>DICT_REGION</code>, <code>DICT_CITY</code></td><td>Адресные данные</td></tr></tbody></table><h3 id="особенности-соответствия" tabindex="-1">Особенности соответствия <a class="header-anchor" href="#особенности-соответствия" aria-label="Permalink to &quot;Особенности соответствия&quot;">​</a></h3><ol><li><strong><code>getCountryDictionary</code></strong> в коде не вызывается — клиент использует локальный файл <code>dict_country.csv</code>. Таблица <code>DICT_COUNTRY</code> в БД существует, но данные берутся из CSV.</li><li><strong><code>RollbackScenario1</code></strong> отправляет пустой объект — при откате <code>issueNewDocument</code> фактические данные не передаются, что может быть связано с особенностями реализации транзакций.</li><li><strong><code>MIG_LABOURMIGDATA</code></strong> и <strong><code>MIG_UNREG_DATA</code></strong> не имеют прямых моделей в <code>Common.Data.Models.Umms</code> — эти таблицы используются для отчетности (форма ИР) и снятия с учета, вероятно через SQL-запросы напрямую.</li></ol>',18)])])}const C=o(a,[["render",r]]);export{_ as __pageData,C as default};
